@test
def test_poisson():
    p = qmc.PoissonDisk(d=2, radius=0.2, rng=11)
    assert close(p.random(8), pd1)
    p = qmc.PoissonDisk(d=2, radius=0.3, rng=11, hypersphere='surface')
    assert close(p.fill_space(), pd2)
    p = qmc.PoissonDisk(d=3, radius=0.25, rng=4, ncandidates=20)
    assert close(p.random(5), pd3)
    assert close(p.random(3), pd3b)

@test
def test_mvn_multinomial():
    m = qmc.MultivariateNormalQMC(mean=[0., 5.], cov=[[1., .5], [.5, 2.]], rng=3)
    assert close(m.random(4), mv1)
    m = qmc.MultivariateNormalQMC(mean=[0., 5., 1.], inv_transform=False, rng=3)
    assert close(m.random(4), mv2)
    mn_ = qmc.MultinomialQMC(pvals=[.2, .3, .5], n_trials=10, rng=5)
    assert close(mn_.random(3), mn)

@test
def test_lhs_sobol():
    assert close(qmc.LatinHypercube(d=3, strength=2, rng=5).random(9), lh2)
    assert close(qmc.LatinHypercube(d=4, strength=2, scramble=False, rng=5).random(25)[:6], lh2b)
    assert close(qmc.Sobol(d=5000, scramble=False).random(4)[:, 4997:], sob_hi)
    assert close(qmc.Sobol(d=21201, scramble=False).random(4)[:, 21199:], sob_hi2)
    assert close(qmc.Sobol(d=3000, rng=2).random(2)[:, 2998:], sob_hi3)

test_poisson()
test_mvn_multinomial()
test_lhs_sobol()
